//! Stateless resets generated by a peer that has lost its connection state.

use super::*;
use crate::{ResetToken, Side};

fn connected() -> ConnPair {
    let mut config = EndpointConfig::default();
    config.cid_generator(Arc::new(|| {
        Box::new(HashedConnectionIdGenerator::from_key(0))
    }));
    let mut builder = ConnPair::builder().enable_multipath();
    builder.client_endpoint_cfg = config.clone();
    builder.server_endpoint_cfg = config;
    let mut pair = builder.connect();
    pair.drive();
    pair
}

fn open_path(pair: &mut ConnPair) -> PathId {
    let remote = pair.routes.public_server_addr();
    let path = pair
        .open_path(
            Client,
            FourTuple::from_remote(remote),
            PathStatus::Available,
        )
        .expect("open another path");
    pair.drive();
    while pair.poll(Client).is_some() {}
    while pair.poll(Server).is_some() {}
    path
}

/// Generate a real reset without forgetting the original endpoint, so negative
/// cases can continue exchanging authenticated packets on the same connection.
fn reset_for(pair: &mut ConnPair, receiver: Side, path: PathId) -> (FourTuple, BytesMut) {
    assert!(pair.client.inbound.is_empty());
    assert!(pair.server.inbound.is_empty());
    let before = pair.path_stats(receiver, path).unwrap().udp_tx.datagrams;
    pair.ping_path(receiver, path).unwrap();
    pair.time += Duration::from_millis(10); // Allow the pacer to run.
    let remote = pair.conn(receiver).network_path(path).unwrap().remote;
    let peer = match receiver {
        Client => {
            pair.drive_client();
            &mut pair.server
        }
        Server => {
            pair.drive_server();
            &mut pair.client
        }
    };
    let (now, packet) = peer.inbound.pop_first().expect("ping reaches the peer");
    let network_path = FourTuple {
        remote: packet.remote,
        local_ip: packet.dst_ip,
    };
    let original = peer
        .endpoint
        .handle(
            now,
            network_path,
            packet.ecn,
            packet.packet.clone(),
            &mut Vec::new(),
        )
        .expect("original endpoint recognizes the actual packet");
    let DatagramEvent::ConnectionEvent(_, original) = original else {
        panic!("ping belongs to the existing connection");
    };
    let ConnectionEventInner::Datagram(original) = original.0 else {
        panic!("expected datagram");
    };
    assert_eq!(original.path_id, path, "verify the actual packet's path");
    let config = peer.endpoint.config().clone();
    let expected_token = ResetToken::new(&*config.reset_key, original.first_decode.dst_cid());
    let mut restarted = Endpoint::new(Arc::new(config), Some(Arc::new(server_config())), true);
    let mut buffer = Vec::new();
    let response = restarted
        .handle(now, network_path, packet.ecn, packet.packet, &mut buffer)
        .expect("restarted peer generates a reset");
    let DatagramEvent::Response(transmit) = response else {
        panic!("expected reset datagram");
    };
    assert_eq!(
        &buffer[transmit.size - crate::RESET_TOKEN_SIZE..transmit.size],
        &expected_token[..],
        "verify reset belongs to the exact CID in use"
    );
    let network_path = FourTuple {
        remote,
        local_ip: Some(transmit.destination.ip()),
    };
    assert!(pair.path_stats(receiver, path).unwrap().udp_tx.datagrams > before);
    (network_path, BytesMut::from(&buffer[..transmit.size]))
}

fn route_reset(
    pair: &mut ConnPair,
    receiver: Side,
    network_path: FourTuple,
    packet: BytesMut,
) -> Option<ConnectionEvent> {
    let now = pair.time;
    let endpoint = match receiver {
        Client => &mut pair.client.endpoint,
        Server => &mut pair.server.endpoint,
    };
    match endpoint.handle(now, network_path, None, packet, &mut Vec::new()) {
        Some(DatagramEvent::ConnectionEvent(_, event)) => Some(event),
        None | Some(DatagramEvent::Response(_)) => None,
        Some(DatagramEvent::NewConnection(_)) => panic!("a reset cannot start a connection"),
    }
}

fn assert_reset(pair: &mut ConnPair, receiver: Side, path: PathId) {
    while pair.poll(receiver).is_some() {}
    let (network, packet) = reset_for(pair, receiver, path);
    let first = route_reset(pair, receiver, network, packet.clone())
        .expect("Endpoint registers the active CID's token");
    let duplicate = route_reset(pair, receiver, network, packet)
        .expect("duplicate reset was queued before draining");
    pair.handle_event(receiver, first);
    pair.handle_event(receiver, duplicate);
    assert_matches!(
        pair.poll(receiver),
        Some(Event::ConnectionLost {
            reason: ConnectionError::Reset
        })
    );
    assert!(pair.poll(receiver).is_none());
    let mut draining = 0;
    let mut drained = 0;
    while let Some(event) = pair.poll_endpoint_events(receiver) {
        draining += usize::from(event.is_draining());
        drained += usize::from(event.is_drained());
    }
    assert_eq!((draining, drained), (1, 1));
}

#[test]
fn voytty_reset_nonzero_path() {
    let _guard = subscribe();
    for receiver in [Client, Server] {
        let mut pair = connected();
        let path = open_path(&mut pair);
        assert_reset(&mut pair, receiver, path);
    }
}

#[test]
fn voytty_reset_after_initial_path_discarded() {
    let _guard = subscribe();
    for receiver in [Client, Server] {
        let mut pair = connected();
        let path = open_path(&mut pair);
        pair.close_path(Client, PathId::ZERO, 0u8.into()).unwrap();
        pair.drive();
        assert!(pair.path_stats(receiver, PathId::ZERO).is_none());
        assert_reset(&mut pair, receiver, path);
    }
}

#[test]
fn voytty_reset_rejects_wrong_source_and_token() {
    let _guard = subscribe();
    for receiver in [Client, Server] {
        let mut pair = connected();
        let path = open_path(&mut pair);
        let (network, packet) = reset_for(&mut pair, receiver, path);
        let mut wrong_source = network;
        wrong_source.remote.set_port(network.remote.port() + 1);
        assert!(route_reset(&mut pair, receiver, wrong_source, packet.clone()).is_none());
        let mut wrong_token = packet.clone();
        let last = wrong_token.len() - 1;
        wrong_token[last] ^= 1;
        assert!(route_reset(&mut pair, receiver, network, wrong_token).is_none());
        assert!(!pair.is_closed(receiver));
        let valid = route_reset(&mut pair, receiver, network, packet)
            .expect("negative controls must not prevent a valid reset");
        pair.handle_event(receiver, valid);
        assert!(pair.is_closed(receiver));
    }
}

#[test]
fn voytty_reset_retired_path_and_queued_reset_are_ignored() {
    let _guard = subscribe();
    for retired in [PathId::ZERO, PathId::from(1u8)] {
        for receiver in [Client, Server] {
            let mut pair = connected();
            let other = open_path(&mut pair);
            let (network, packet) = reset_for(&mut pair, receiver, retired);
            let queued = route_reset(&mut pair, receiver, network, packet.clone())
                .expect("token is active before abandonment");
            pair.close_path(receiver, retired, 0u8.into()).unwrap();
            // Endpoint retirement has not yet been processed. A queued packet
            // must still be checked against the connection's current CIDs.
            pair.handle_event(receiver, queued);
            assert!(!pair.is_closed(receiver));
            pair.drive();
            assert!(route_reset(&mut pair, receiver, network, packet).is_none());
            let active = if retired == PathId::ZERO {
                other
            } else {
                PathId::ZERO
            };
            assert_reset(&mut pair, receiver, active);
        }
    }
}

#[test]
fn voytty_reset_after_network_change_rotates_cids() {
    let _guard = subscribe();
    #[derive(Debug)]
    struct Recoverable;
    impl crate::NetworkChangeHint for Recoverable {
        fn is_path_recoverable(&self, _: PathId, _: FourTuple) -> bool {
            true
        }
    }
    for path in [PathId::ZERO, PathId::from(1u8)] {
        let mut pair = connected();
        open_path(&mut pair);
        let (network, old_packet) = reset_for(&mut pair, Client, path);
        let queued = route_reset(&mut pair, Client, network, old_packet.clone())
            .expect("token is active before rotation");
        let now = pair.time;
        pair.conn_mut(Client).handle_network_change(Some(&Recoverable), now);
        pair.handle_event(Client, queued);
        assert!(!pair.is_closed(Client));
        pair.drive();
        assert!(route_reset(&mut pair, Client, network, old_packet).is_none());
        assert_reset(&mut pair, Client, path);
    }
}

#[test]
fn voytty_reset_after_peer_address_migration() {
    let _guard = subscribe();
    for path in [PathId::ZERO, PathId::from(1u8)] {
        let mut pair = connected();
        open_path(&mut pair);
        let old = pair.conn(Server).network_path(path).unwrap().remote;
        pair.routes.as_basic_mut().passive_migration(Client);
        pair.ping_path(Client, path).unwrap();
        pair.drive();
        assert_ne!(pair.conn(Server).network_path(path).unwrap().remote, old);
        assert_reset(&mut pair, Server, path);
    }
}

#[test]
fn voytty_reset_with_known_cid_still_checks_source_and_retirement() {
    let _guard = subscribe();
    for receiver in [Client, Server] {
        for retired in [false, true] {
            let mut pair = connected();
            let active = open_path(&mut pair);
            let (network, reset) = reset_for(&mut pair, receiver, PathId::ZERO);
            // Reuse a real packet's known CID prefix. This bypasses Endpoint's
            // token lookup, so the connection must enforce the same checks.
            let sender = if receiver == Client { Server } else { Client };
            pair.ping_path(sender, active).unwrap();
            pair.time += Duration::from_millis(10);
            let inbound = if receiver == Client {
                pair.drive_server();
                &mut pair.client.inbound
            } else {
                pair.drive_client();
                &mut pair.server.inbound
            };
            let (_, packet) = inbound.pop_first().expect("peer sends on active path");
            let mut packet = packet.packet;
            let end = packet.len();
            packet[end - crate::RESET_TOKEN_SIZE..]
                .copy_from_slice(&reset[reset.len() - crate::RESET_TOKEN_SIZE..]);
            let mut source = network;
            if retired {
                pair.close_path(receiver, PathId::ZERO, 0u8.into()).unwrap();
            } else {
                source.remote.set_port(source.remote.port() + 1);
            }
            let event = route_reset(&mut pair, receiver, source, packet)
                .expect("known CID routes even an invalid reset");
            pair.handle_event(receiver, event);
            assert!(!pair.is_closed(receiver));
            pair.drive();
            assert_reset(&mut pair, receiver, active);
        }
    }
}
